package coding

import (
	"encoding/json"
	"os"
	"testing"
)

// coding.MatchGlob is a hand port of the minimatch subset the model-scope
// resolution uses, so the corpus is generated by the library itself
// (testdata/glob-minimatch/generate.mjs, nocase like the caller) instead of by
// the port's own expectations.
func TestMatchGlobMatchesMinimatch(t *testing.T) {
	raw, err := os.ReadFile("testdata/glob-minimatch/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden struct {
		Cases []struct {
			Pattern string `json:"pattern"`
			Value   string `json:"value"`
			Match   bool   `json:"match"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatal(err)
	}
	if len(golden.Cases) == 0 {
		t.Fatal("golden has no cases")
	}
	for _, testCase := range golden.Cases {
		if got := MatchGlob(testCase.Pattern, testCase.Value, true); got != testCase.Match {
			t.Errorf("MatchGlob(%q, %q, nocase) = %v, minimatch says %v",
				testCase.Pattern, testCase.Value, got, testCase.Match)
		}
	}
}
